PASSES = {'boundary', 'complete_manifest', 'domains', 'candidate_challenge', 'validation', 'contradictions', 'handoff'}
SESSION = None


def audit(report):
    gaps = []
    ids = [x['id'] for x in report.get('coverage', [])]
    if set(ids) != EXPECTED or len(ids) != len(EXPECTED):
        gaps.append('Coverage missing/extra/duplicate IDs: ' + repr(sorted(EXPECTED - set(ids))) + ' / ' + repr(sorted(set(ids) - EXPECTED)))
    for row in report.get('coverage', []):
        if not row.get('behavior_reviewed', '').strip() or not row.get('reading_evidence', '').strip():
            gaps.append('No substantive read evidence: ' + row['id'])
    ps = {x['id']: x for x in report.get('passes', [])}
    for p in PASSES:
        if p not in ps or ps[p].get('status') == 'incomplete' or not ps[p].get('evidence', '').strip():
            gaps.append('Mandatory pass unfinished: ' + p)
    scope = {x['target']: x for x in report.get('scope', [])}
    for target in TARGETS:
        actual = scope.get(target['id'], {})
        for field in ('head', 'base', 'merge_base'):
            if actual.get(field) != target[field]:
                gaps.append('Wrong/missing revision: ' + target['id'] + ':' + field)
    obligations = report.get('obligations_and_criteria', [])
    if not obligations:
        gaps.append('No individually enumerated obligations/criteria')
    gaps.extend('Uncovered obligation: ' + x['id'] for x in obligations if x['status'] == 'incomplete')
    complete = report.get('completeness', {})
    if not complete.get('complete') or complete.get('manifest_count') != len(EXPECTED) or complete.get('reviewed_count') != len(EXPECTED) or complete.get('missing_ids'):
        gaps.append('Completeness accounting does not match independently materialized manifest')
    if report.get('verdict') not in ('PASS', 'CHANGES REQUIRED', 'UNVERIFIED'):
        gaps.append('Informal or absent verdict')
    if report.get('verdict') == 'PASS' and report.get('findings'):
